    new_col_values = [["A", "B", "C"], ["D", "E", "F"]]
    result = ws.insert_cols(new_col_values, 2)
    print("Test passed: insert_cols executed successfully")
except Exception as e:
    print(f"Test failed with error: {e}")
    import traceback
    traceback.print_exc()
